import asyncio
R='us-east-1'
SGS={'alb':'sg-05c6c273af3f5fbaf','app':'sg-05a80513688f73551','db':'sg-0adcad843d7f39840'}
out={}
async def safe(**kw):
    try: return await call_boto3(**kw)
    except Exception as e: return {'error':str(e)}
async def main():
    out['subnet_group'] = await safe(service_name='rds', operation_name='DeleteDBSubnetGroup', region_name=R, params={'DBSubnetGroupName':'umami-acs3b14131d-subnets'})
    # snapshots left behind by this instance?
    snaps = await safe(service_name='rds', operation_name='DescribeDBSnapshots', region_name=R, params={'DBInstanceIdentifier':'umami-acs3b14131d-pg'})
    out['snapshots'] = snaps if 'error' in snaps else [s['DBSnapshotIdentifier'] for s in snaps.get('DBSnapshots',[])]
    # strip rules first so cross-SG references don't block deletion
    desc = await safe(service_name='ec2', operation_name='DescribeSecurityGroups', region_name=R, params={'GroupIds':list(SGS.values())})
    for g in desc.get('SecurityGroups',[]):
        if g.get('IpPermissions'):
            await safe(service_name='ec2', operation_name='RevokeSecurityGroupIngress', region_name=R, params={'GroupId':g['GroupId'],'IpPermissions':g['IpPermissions']})
        if g.get('IpPermissionsEgress'):
            await safe(service_name='ec2', operation_name='RevokeSecurityGroupEgress', region_name=R, params={'GroupId':g['GroupId'],'IpPermissions':g['IpPermissionsEgress']})
    for name,sg in SGS.items():
        for attempt in range(12):
            r = await safe(service_name='ec2', operation_name='DeleteSecurityGroup', region_name=R, params={'GroupId':sg})
            if 'error' not in r:
                out[f'sg_{name}']='deleted'; break
            if 'NotFound' in r['error']:
                out[f'sg_{name}']='already gone'; break
            out[f'sg_{name}']=r['error']
            await asyncio.sleep(15)
    return out
result = await main()
result
